from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class DistNames(SchemaObject):
    config = SchemaField(name='config')
    runtime = SchemaField(name='runtime')

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime

        super(DistNames, self).__init__()


class NetworkSlicing(SchemaObject):
    snssai_id = SchemaField(name='snssai_id', not_null=True)
    sst = SchemaField(name='sst', not_null=True)
    sd = SchemaField(name='sd')
    user_label = SchemaField(name='user_label')
    nr_plmn_dn_list = SchemaField(name='nr_plmn_dn_list', not_null=True, many=True)
    administrative_state = SchemaField(name='administrative_state', not_null=True)
    operational_state = SchemaField(name='operational_state')
    alarms = SchemaField(name='alarms', not_null=True)
    dist_names = SchemaField(name='dist_names', not_null=True, klass=DistNames)

    def __init__(self, snssai_id, sst, sd, user_label, nr_plmn_dn_list, administrative_state, operational_state,
                 alarms, dist_names):
        self.snssai_id = snssai_id
        self.sst = sst
        self.sd = sd
        self.user_label = user_label
        self.nr_plmn_dn_list = nr_plmn_dn_list
        self.administrative_state = administrative_state
        self.operational_state = operational_state
        self.alarms = alarms
        self.dist_names = dist_names

        super(NetworkSlicing, self).__init__()


class NetworkSlicingDiffV1(SchemaObject):
    revision = SchemaField(name='revision', not_null=True)
    created = SchemaField(name='created', not_null=True)
    updated = SchemaField(name='updated', not_null=True)
    removed = SchemaField(name='removed', not_null=True)

    def __init__(self, revision, created, updated, removed):
        self.revision = revision
        self.created = created
        self.updated = updated
        self.removed = removed

        super(NetworkSlicingDiffV1, self).__init__()
